(function () {
  var RTL = ["ar"], KEY = "cgg-lang";
  function each(list, fn) { for (var i = 0; i < list.length; i++) fn(list[i], i); }
  function apply(lang) {
    if (!CGG_TRANSLATIONS[lang]) lang = "en";
    var dict = CGG_TRANSLATIONS[lang];
    each(document.querySelectorAll("[data-i18n]"), function (el) {
      var k = el.getAttribute("data-i18n");
      if (dict[k] !== undefined) el.innerHTML = dict[k];
    });
    document.documentElement.setAttribute("lang", lang);
    document.documentElement.setAttribute("dir", RTL.indexOf(lang) !== -1 ? "rtl" : "ltr");
    each(document.querySelectorAll(".lang-switch button"), function (b) {
      var on = b.getAttribute("data-lang") === lang;
      b.classList.toggle("active", on);
      b.setAttribute("aria-pressed", String(on));
    });
    try { localStorage.setItem(KEY, lang); } catch (e) {}
    try { document.dispatchEvent(new CustomEvent("cgg:lang", { detail: lang })); } catch (e) {}
  }
  document.addEventListener("DOMContentLoaded", function () {
    var saved = "en";
    try { saved = localStorage.getItem(KEY) || "en"; } catch (e) {}
    if (saved !== "en") apply(saved); else apply("en");
    each(document.querySelectorAll(".lang-switch button"), function (b) {
      b.addEventListener("click", function () { apply(b.getAttribute("data-lang")); });
    });
  });
})();
